import { _decorator, assert, Button, Component, director, error, Prefab, ProgressBar, resources } from "cc";
import { GlobalData } from "../manager/GlobalData";

const { ccclass, property } = _decorator;

@ccclass('Loading')
export class Loading extends Component {

    @property(ProgressBar)
    progressBar: ProgressBar = null;

    @property(Button)
    joginGame: Button = null;

    private preloadList: string[] = [
        'prefab',
        'prefab/game',
        'prefab/gameEndScore',
        'prefab/gameEndScoreRank',
        'prefab/room'
    ];

    private prefabNames: string[] = [];
    private total = 0;
    private finished = 0;

    start() {
        this.loadAllPrefabs().then(() => {
            this.loadMainScene();
        });
    }

    private async loadAllPrefabs() {
        // resources.loadDir('prefab', Prefab, async (err, assets) => {
        //     if (err) {
        //         console.error('加载 prefab 失败', err);
        //         return;
        //     }

        //     this.total = assets.length;

        //     for (const asset of assets) {
        //         // ✅ 这里不再重新加载，只是模拟加载延迟
        //         await this.simulateDelay(10); // 可根据需求调整速度
        //         this.finished++;
        //         this.updateProgress();
        //     }
        // });
        resources.loadDir('prefab', (completedCount, totalCount, item) => {
            console.log(completedCount, totalCount)
            let progress = parseFloat(((completedCount) / (totalCount)).toFixed(3));
            this.updateProgress(progress);
        }, (error, assets) => {

        })
    }

    private loadMainScene() {
        const sceneName = GlobalData.sceneName.lobby;
        director.preloadScene(sceneName, (completedCount, totalCount) => {
            const sceneProgress = completedCount / totalCount;
            const totalProgress = (this.finished + sceneProgress) / (this.total + 1);
            this.updateProgress(totalProgress);
        }, () => {
            // director.loadScene(sceneName);
        });
    }

    private simulateDelay(ms: number): Promise<void> {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    private updateProgress(p: number) {
        this.progressBar.progress = p;
        // this.tipLabel.string = `加载中 ${Math.floor(p * 100)}%`;
    }

}